@lru_cache(maxsize=None)
def get_prime_factorization(num):
    factors = {}
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

@lru_cache(maxsize=None)
def get_factor_partitions(n):
    if n == 1:
        return [[]]
    partitions = [[[n]]]
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            sub_partitions = get_factor_partitions(n // i)
            for part in sub_partitions:
                partitions.append(sorted([i] + part))
    # Remove duplicates by converting to tuple and using a set
    return list(set(tuple(p) for p in partitions))

