def smallest_n_with_tau(t, forbidden_primes_tuple):
    forbidden_primes = set(forbidden_primes_tuple)
    if t == 1:
        return 1

    available_primes = [p for p in _primes if p not in forbidden_primes]

    min_n = float('inf')

    factor_partitions = get_factor_partitions(t)

